class Solution {
public:
    int combinationSum4(vector<int>& nums, int target) {
        vector<unsigned long long> ways(target + 1, 0);
        ways[0] = 1;
        for (int a = 1; a <= target; a++) {
            for (int c = 0; c < (int)nums.size(); c++) {
                if (nums[c] <= a) ways[a] += ways[a - nums[c]];
            }
        }
        return ways[target];
    }
};
